-- OPHWC Test Data Script
-- Run as: mysql -u root -p ophwc < test_data.sql
-- Password ALL users: allow | Safe to run multiple times

USE ophwc;

-- 1. USER TYPES (table: user_types)

-- 2. DIVISIONS (table: divisions)

-- 3. NATURE OF WORK (table: nature_of_work)

-- 4. PROJECT STATUS (table: project_status)

-- 5. FLOORS (table: floors)

-- 6. FLOOR WORK (table: floor_work)
-- 7. USERS (table: user, columns: division_id, user_type, username, password, first_name, last_name, phone_num, email_id, status)
-- 8. PROJECTS (table: projects, NOTE: nature column is natur_of_project - typo in DB)
-- 9. PROJECT RESOURCES (table: project_resources, columns: project_id, user_id, nature_of_project, status)

-- 10. PROJECT AMOUNTS (table: project_amount, columns: project_id, amount, remarks, created_date, from_date, to_date)

-- VERIFICATION
SELECT 'user_types' AS tbl, COUNT(*) AS cnt FROM user_types UNION ALL SELECT 'divisions', COUNT(*) FROM divisions UNION ALL SELECT 'nature_of_work', COUNT(*) FROM nature_of_work UNION ALL SELECT 'project_status', COUNT(*) FROM project_status UNION ALL SELECT 'floors', COUNT(*) FROM floors UNION ALL SELECT 'floor_work', COUNT(*) FROM floor_work UNION ALL SELECT 'user', COUNT(*) FROM user UNION ALL SELECT 'projects', COUNT(*) FROM projects UNION ALL SELECT 'project_resources', COUNT(*) FROM project_resources UNION ALL SELECT 'project_amount', COUNT(*) FROM project_amount;
SELECT u.username, ut.type_name AS role, d.division_name AS division, u.status FROM user u JOIN user_types ut ON u.user_type=ut.id JOIN divisions d ON u.division_id=d.id ORDER BY ut.type_name, u.username;
